#pragma bank 5

#include "ui.h"
#include <gb/gb.h>

/* Battle hand-card frame tiles (generated by make gfx from
 * assets/card_frames.png; loaded to VRAM at UI_TILE_CARD_FRAME_BASE by
 * ui_init).  Bank-5 const data: readable from this banked loader.  Moved
 * out of ui_battle_content.c (bank 3) with the loader below to relieve
 * the release bank-3 budget for the defend counter forecast. */
#include "gfx/card_frame_tiles.h"

/* Battle UI tile loader (bank-5 body behind the fixed-bank
 * ui_card_tiles_load() wrapper, dispatched once from ui_init with the LCD
 * off): streams the card frame tiles, the turn-timer bar segments, the
 * HUD hp/ap/deck icons and the light/dark select arrows from THIS bank's
 * data (generated card_frame_tiles.h) into VRAM block 1.  Reads its own
 * bank-local data directly (no banked_copy, which would restore the home
 * bank mid-body -- banked.h ABI) and writes VRAM at the SIGNED BG tile
 * addresses (0x9000 + id*16 -- LCDC.4 = 0, see the loop comment below and
 * AGENTS.md 52.22).  VRAM: frames 118-126, bar filled 117 / empty 127,
 * HUD icons at 113 (hp), 114 (ap) and 116 (deck), light arrow at 96,
 * dark arrow at 110, weapons at 104-108, ring X at 115.  (Gold prices
 * render as the plain font capital 'G'; the old coin tile 115 is now
 * the ring X.) */
/* Sheet order (compose_card_frames.py): frames are tiles 0-8 (VRAM
 * 118-126), filled is tile 9 (VRAM 117), empty is tile 10 (VRAM 127),
 * HUD icons are tiles 11-13 (VRAM 113/114/116), the light select arrow
 * is tile 14 (VRAM 96), the dark select arrow is tile 15 (VRAM 110). */
static const uint8_t s_card_tile_vram_ids[32] = {
    118, 119, 120, 121, 122, 123, 124, 125, 126,  /* card frame TL..BR */
    117, 127,                                     /* bar filled, empty */
    113, 114, 116,                                /* HUD: hp, ap, deck */
    96,                                           /* light select arrow */
    110, 111, 112,                                /* dark arrow + 2 blanks (grid cells 15-17) */
    104, 105, 106, 107, 108,                      /* weapons: sword, shield, bow, dagger, ring */
    115,                                          /* ring power-slot X (retired coin slot) */
    /* Limited-use arrow counters (bow floor row, shared by HEAL rings):
     * uses 0/1/2/3, power icon, trailing blank at the unused BG fetch
     * slot 103, then the appended 4- and 5-arrow cells.  Ids 97/98-103
     * are free BG fetch slots: the font covers 0-95 and no tilemap ever
     * references them (their same-numbered OAM ids live in the 0x8000
     * sprite block — a different physical address, AGENTS.md 52.22).
     * The row-7/row-9 blanks load white first; the appended cells
     * overwrite VRAM 97/103 right after (nothing reads the blanks). */
    98, 99, 100, 101, 102, 103,                   /* arrows 0, 1, 2, 3, nine, blank */
    97, 103,                                      /* arrows 4, 5 (appended cells) */
};

/* Dialogue continue chevron (VRAM 109, UI_TILE_DIALOGUE_CONTINUE): the
 * intrepid ">" glyph (font tile 30) rotated 90 degrees clockwise so it
 * points down.  Monochrome doubles (lo == hi, shade 3 ink on shade 0
 * paper, like the font): rows decode to a down chevron 7 wide at the
 * top narrowing to 1 at row 6.  Lives here so the fixed bank pays
 * nothing for it (same LCD-off window as the coin tile above). */
static const uint8_t s_dialogue_continue_tile[16] = {
    0x00, 0x00,
    0x00, 0x00,
    0x41, 0x41,
    0x63, 0x63,
    0x36, 0x36,
    0x1C, 0x1C,
    0x08, 0x08,
    0x00, 0x00
};

void ui_card_tiles_load_banked(void)
{
    uint8_t i, j;
    volatile uint8_t *dst;
    const uint8_t *src;

    for (i = 0; i < 32; i++) {
        /* Signed BG tile addressing (LCDC.4 = 0, set in ui_init and never
         * restored): BG tile ids < 128 are fetched by the PPU from
         * 0x9000 + id*16, NOT from the sprite-addressable 0x8000 block.
         * All 32 ids are <= 127, so the physical address is 0x9000-based.
         * Raw writes to 0x8000 + id*16 land in VRAM the BG never reads
         * (mGBA watchpoint regression: AGENTS.md 52.22).  Ids >= 128
         * (world/enemy art) map to 0x8800 + (id-128)*16, which their own
         * raw writer already targets. */
        dst = (volatile uint8_t *)(0x9000u + ((uint16_t)s_card_tile_vram_ids[i] << 4));
        src = card_frame_tiles + ((uint16_t)i << 4);
        for (j = 0; j < 16; j++) {
            dst[j] = src[j];
        }
    }
    /* Dialogue continue chevron (VRAM 109): same signed addressing. */
    dst = (volatile uint8_t *)(0x9000u + ((uint16_t)UI_TILE_DIALOGUE_CONTINUE << 4));
    for (j = 0; j < 16; j++) {
        dst[j] = s_dialogue_continue_tile[j];
    }
}

